mapper.sql:
service_name = #{serviceName}
AND ((corpus_type = 'LOG' AND incident_code = #{incidentCode})
  OR (corpus_type = 'RUNBOOK' AND incident_code IS NULL))

mapper.select:
SELECT id, chunk_id, corpus_type, service_name, title, keywords, sequence_order, CHAR_LENGTH(content) AS content_length FROM corpus_chunks WHERE AND corpus_type = #{corpusType}
AND ( INSTR(title, #{keyword}) > 0 OR INSTR(keywords, #{keyword}) > 0 OR INSTR(service_name, #{keyword}) > 0 )
ORDER BY sequence_order, chunk_id
